          'misc': '1.0.0',
          'agents': {'zeta': '3.0.0'},
        }),
      ),
    });
    try {
      final r = AgentPackResolver(
        packsRoot: packsRoot,
        registryBaseUrl: 'http://127.0.0.1:${server.port}',
      );
      expect(
        () => r.resolve('demo@latest'),
        throwsA(
          isA<AgentPackException>()
              .having(
                (e) => e.message,
                'message',
                contains("Agent 'demo' not found in registry catalog"),
              )
              .having(
