144	  int _findEocdrSignature(InputStreamBase input) {
145	    final pos = input.position;
146	    final length = input.length;
147	
148	    // The directory and archive contents are written to the end of the zip
149	    // file. We need to search from the end to find these structures,
150	    // starting with the 'End of central directory' record (EOCD).
151	    for (var ip = length - 5; ip >= 0; --ip) {
152	      input.position = ip;
153	      final sig = input.readUint32();
154	      if (sig == eocdLocatorSignature) {
155	        input.position = pos;
156	        return ip;
157	      }
158	    }
159	    throw ArchiveException('Could not find End of Central Directory Record');
160	  }
161	}

