 51	        input.subset(centralDirectoryOffset, centralDirectorySize);
 52	
 53	    final dirStream = InputStream(dirContent.toUint8List());
 54	    while (!dirStream.isEOS) {
 55	      final fileSig = dirStream.readUint32();
 56	      if (fileSig != ZipFileHeader.SIGNATURE) {
 57	        break;
 58	      }
 59	      fileHeaders.add(ZipFileHeader(dirStream));
 60	    }
 61	
 62	    for (final file in fileHeaders) {
 63	      file.readLocalFileHeader(input, password);
 64	    }
 65	  }
 66	
 67	  void _readZip64Data(InputStreamBase input) {
 68	    final ip = input.position;
 69	    // Check for zip64 data.
 70	
 71	    // Zip64 end of central directory locator
 72	    // signature                       4 bytes  (0x07064b50)
 73	    // number of the disk with the
 74	    // start of the zip64 end of
 75	    // central directory               4 bytes
 76	    // relative offset of the zip64
 77	    // end of central directory record 8 bytes
 78	    // total number of disks           4 bytes
 79	
 80	    final locPos = filePosition - zip64EocdLocatorSize;
 81	    if (locPos < 0) {
 82	      return;
 83	    }
 84	    final zip64 = input.subset(locPos, zip64EocdLocatorSize);
 85	
 86	    var sig = zip64.readUint32();
 87	    // If this isn't the signature we're looking for, nothing more to do.
 88	    if (sig != zip64EocdLocatorSignature) {
 89	      input.position = ip;
 90	      return;
 91	    }
 92	
 93	    final startZip64Disk = zip64.readUint32(); // ignore: unused_local_variable
 94	    final zip64DirOffset = zip64.readUint64();
 95	    final numZip64Disks = zip64.readUint32(); // ignore: unused_local_variable
 96	
 97	    // Zip64 end of central directory record
 98	    // signature                       4 bytes  (0x06064b50)
 99	    // size of zip64 end of central
100	    // directory record                8 bytes
101	    // version made by                 2 bytes
102	    // version needed to extract       2 bytes
103	    // number of this disk             4 bytes
104	    // number of the disk with the
105	    // start of the central directory  4 bytes
106	    // total number of entries in the
107	    // central directory on this disk  8 bytes
108	    // total number of entries in the
109	    // central directory               8 bytes
110	    // size of the central directory   8 bytes
111	    // offset of start of central
112	    // directory with respect to
113	    // the starting disk number        8 bytes
114	    // zip64 extensible data sector    (variable size)
115	    input.position = zip64DirOffset;
116	
117	    sig = input.readUint32();
118	    if (sig != zip64EocdSignature) {
119	      input.position = ip;
120	      return;
121	    }
122	
123	    final zip64EOCDSize = input.readUint64(); // ignore: unused_local_variable
124	    final zip64Version = input.readUint16(); // ignore: unused_local_variable
125	    // ignore: unused_local_variable
126	    final zip64VersionNeeded = input.readUint16();
127	    final zip64DiskNumber = input.readUint32();
128	    final zip64StartDisk = input.readUint32();
129	    final zip64NumEntriesOnDisk = input.readUint64();
130	    final zip64NumEntries = input.readUint64();
131	    final dirSize = input.readUint64();
132	    final dirOffset = input.readUint64();
133	
134	    numberOfThisDisk = zip64DiskNumber;
135	    diskWithTheStartOfTheCentralDirectory = zip64StartDisk;
136	    totalCentralDirectoryEntriesOnThisDisk = zip64NumEntriesOnDisk;
137	    totalCentralDirectoryEntries = zip64NumEntries;
138	    centralDirectorySize = dirSize;
139	    centralDirectoryOffset = dirOffset;
140	
141	    input.position = ip;
142	  }
143	
144	  int _findEocdrSignature(InputStreamBase input) {
145	    final pos = input.position;
146	    final length = input.length;
147	
148	    // The directory and archive contents are written to the end of the zip
149	    // file. We need to search from the end to find these structures,
150	    // starting with the 'End of central directory' record (EOCD).
151	    for (var ip = length - 5; ip >= 0; --ip) {
152	      input.position = ip;
153	      final sig = input.readUint32();
154	      if (sig == eocdLocatorSignature) {
155	        input.position = pos;
156	        return ip;
157	      }
158	    }
159	    throw ArchiveException('Could not find End of Central Directory Record');
160	  }
161	}

