 27	class ZipFile extends FileContent {
 28	  static const int zipCompressionStore = 0;
 29	  static const int zipCompressionDeflate = 8;
 30	  static const int zipCompressionBZip2 = 12;
 31	  static const int zipCompressionAexEncryption = 99;
 32	
 33	  static const int zipFileSignature = 0x04034b50;
 34	
 35	  int signature = zipFileSignature; // 4 bytes
 36	  int version = 0; // 2 bytes
 37	  int flags = 0; // 2 bytes
 38	  int compressionMethod = 0; // 2 bytes
 39	  int lastModFileTime = 0; // 2 bytes
 40	  int lastModFileDate = 0; // 2 bytes
 41	  int? crc32; // 4 bytes
 42	  int? compressedSize; // 4 bytes
 43	  int? uncompressedSize; // 4 bytes
 44	  String filename = ''; // 2 bytes length, n-bytes data
 45	  List<int> extraField = []; // 2 bytes length, n-bytes data
 46	  ZipFileHeader? header;
 47	
 48	  ZipFile([InputStreamBase? input, this.header, String? password]) {
 49	    if (input != null) {
 50	      signature = input.readUint32();
 51	      if (signature != zipFileSignature) {
 52	        throw ArchiveException('Invalid Zip Signature');
 53	      }
 54	
 55	      version = input.readUint16();
 56	      flags = input.readUint16();
 57	      compressionMethod = input.readUint16();
 58	      lastModFileTime = input.readUint16();
 59	      lastModFileDate = input.readUint16();
 60	      crc32 = input.readUint32();
 61	      compressedSize = input.readUint32();
 62	      uncompressedSize = input.readUint32();
 63	      final fnLen = input.readUint16();
 64	      final exLen = input.readUint16();
 65	      filename = input.readString(size: fnLen);
 66	      extraField = input.readBytes(exLen).toUint8List();
 67	
 68	      // Use the compressedSize and uncompressedSize from the CFD header.
 69	      // For Zip64, the sizes in the local header will be 0xFFFFFFFF.
 70	      compressedSize = header?.compressedSize ?? compressedSize;
 71	      uncompressedSize = header?.uncompressedSize ?? uncompressedSize;
 72	
 73	      _encryptionType =
 74	          (flags & 0x1) != 0 ? encryptionZipCrypto : encryptionNone;
 75	      _password = password;
 76	
 77	      // Read compressedSize bytes for the compressed data.
 78	      _rawContent = input.readBytes(header!.compressedSize!);
 79	
 80	      if (_encryptionType != 0 && exLen > 2) {
 81	        final extra = InputStream(extraField);
 82	        while (!extra.isEOS) {
 83	          final id = extra.readUint16();
 84	          final size = extra.readUint16();
 85	          final extraBytes = extra.readBytes(size);
 86	          if (id == AesHeader.signature) {
 87	            final vendorVersion = extraBytes.readUint16();
 88	            final vendorId = extraBytes.readString(size: 2);
 89	            final encryptionStrength = extraBytes.readByte();
 90	            final compressionMethod = extraBytes.readUint16();
 91	
 92	            _encryptionType = encryptionAes;
 93	            _aesHeader = AesHeader(
 94	                vendorVersion, vendorId, encryptionStrength, compressionMethod);
 95	
 96	            // compressionMethod in the file header will be 99 for aes encrypted
 97	            // files. The compressionMethod value in the AES extraField stores
 98	            // the actual compressionMethod.
 99	            this.compressionMethod = _aesHeader!.compressionMethod;
100	          }
101	        }
102	      }
103	
104	      if (_encryptionType == 1 && password != null) {
105	        _initKeys(password);
106	      }
107	
108	      // If bit 3 (0x08) of the flags field is set, then the CRC-32 and file
109	      // sizes are not known when the header is written. The fields in the
110	      // local header are filled with zero, and the CRC-32 and size are
111	      // appended in a 12-byte structure (optionally preceded by a 4-byte
112	      // signature) immediately after the compressed data:
113	      if (flags & 0x08 != 0) {
114	        final sigOrCrc = input.readUint32();
115	        if (sigOrCrc == 0x08074b50) {
116	          crc32 = input.readUint32();
117	        } else {
118	          crc32 = sigOrCrc;
119	        }
