10	
11	/// Decode a zip formatted buffer into an [Archive] object.
12	class ZipDecoder {
13	  late ZipDirectory directory;
14	
15	  Archive decodeBytes(List<int> data, {bool verify = false, String? password}) {
16	    return decodeBuffer(InputStream(data), verify: verify, password: [REDACTED:Sensitive Value]);
17	  }
18	
19	  Archive decodeBuffer(
20	    InputStreamBase input, {
21	    bool verify = false,
22	    String? password,
23	  }) {
24	    directory = ZipDirectory.read(input, password: [REDACTED:Sensitive Value]);
25	    final archive = Archive();
26	
27	    for (final zfh in directory.fileHeaders) {
28	      final zf = zfh.file!;
29	
30	      // The attributes are stored in base 8
31	      final mode = zfh.externalFileAttributes!;
32	      final compress = zf.compressionMethod != ZipFile.zipCompressionStore;
33	
34	      if (verify) {
35	        final computedCrc = getCrc32(zf.content);
36	        if (computedCrc != zf.crc32) {
37	          throw ArchiveException('Invalid CRC for file in archive.');
38	        }
39	      }
40	
41	      //dynamic content = zf.rawContent;
42	      final file = ArchiveFile(
43	          zf.filename, zf.uncompressedSize!, zf, zf.compressionMethod);
44	
45	      file.mode = mode >> 16;
46	
47	      // see https://github.com/brendan-duncan/archive/issues/21
48	      // UNIX systems has a creator version of 3 decimal at 1 byte offset
49	      if (zfh.versionMadeBy >> 8 == 3) {
50	        file.isFile = false;
51	
52	        final fileType = file.mode & 0xF000;
53	        switch (fileType) {
54	          case 0x8000:
55	          case 0x0000: // No determination can be made so we assume it's a file.
56	            file.isFile = true;
57	            break;
58	          case 0xA000:
59	            file.isSymbolicLink = true;
60	            file.nameOfLinkedFile = utf8.decode(file.content as List<int>);
61	            break;
62	          default:
63	        }
64	      } else {
65	        file.isFile = !file.name.endsWith('/');
66	      }
67	
68	      file.crc32 = zf.crc32;
69	      file.compress = compress;
70	      file.lastModTime = zf.lastModFileDate << 16 | zf.lastModFileTime;
71	
72	      archive.addFile(file);
73	    }
74	
75	    return archive;
76	  }
77	}

