 67	  void _readZip64Data(InputStreamBase input) {
 68	    final ip = input.position;
 69	    // Check for zip64 data.
 70	
 71	    // Zip64 end of central directory locator
 72	    // signature                       4 bytes  (0x07064b50)
 73	    // number of the disk with the
 74	    // start of the zip64 end of
 75	    // central directory               4 bytes
 76	    // relative offset of the zip64
 77	    // end of central directory record 8 bytes
 78	    // total number of disks           4 bytes
 79	
 80	    final locPos = filePosition - zip64EocdLocatorSize;
 81	    if (locPos < 0) {
 82	      return;
 83	    }
 84	    final zip64 = input.subset(locPos, zip64EocdLocatorSize);
 85	
 86	    var sig = zip64.readUint32();
 87	    // If this isn't the signature we're looking for, nothing more to do.
 88	    if (sig != zip64EocdLocatorSignature) {
 89	      input.position = ip;
 90	      return;
 91	    }
 92	
 93	    final startZip64Disk = zip64.readUint32(); // ignore: unused_local_variable
 94	    final zip64DirOffset = zip64.readUint64();
 95	    final numZip64Disks = zip64.readUint32(); // ignore: unused_local_variable
 96	
 97	    // Zip64 end of central directory record
 98	    // signature                       4 bytes  (0x06064b50)
 99	    // size of zip64 end of central
100	    // directory record                8 bytes
101	    // version made by                 2 bytes
102	    // version needed to extract       2 bytes
103	    // number of this disk             4 bytes
104	    // number of the disk with the
105	    // start of the central directory  4 bytes
106	    // total number of entries in the
107	    // central directory on this disk  8 bytes
108	    // total number of entries in the
109	    // central directory               8 bytes
110	    // size of the central directory   8 bytes
111	    // offset of start of central
112	    // directory with respect to
