    Map<String, dynamic> manifest(String agent, String version) => {
          'agent': agent,
          'version': version,
          'defaultEntry': 'a.json',
          'files': [
            {'path': 'a.json', 'sha256': sha256Of('{}')},
          ],
        };

    test('rejects an agent with a path separator', () {
