 32	      crc32 = input.readUint32();
 33	      compressedSize = input.readUint32();
 34	      uncompressedSize = input.readUint32();
 35	      final fnameLen = input.readUint16();
 36	      final extraLen = input.readUint16();
 37	      final commentLen = input.readUint16();
 38	      diskNumberStart = input.readUint16();
 39	      internalFileAttributes = input.readUint16();
 40	      externalFileAttributes = input.readUint32();
 41	      localHeaderOffset = input.readUint32();
 42	
 43	      if (fnameLen > 0) {
 44	        filename = input.readString(size: fnameLen);
 45	      }
 46	
 47	      if (extraLen > 0) {
 48	        final extraBytes = input.readBytes(extraLen);
 49	        extraField = extraBytes.toUint8List();
 50	
 51	        final extra = InputStream(extraField);
 52	        while (!extra.isEOS) {
 53	          final id = extra.readUint16();
 54	          var size = extra.readUint16();
 55	          final extraBytes = extra.readBytes(size);
 56	          if (id == 1) {
 57	            // Zip64 extended information
 58	            // The following is the layout of the zip64 extended
 59	            // information "extra" block. If one of the size or
 60	            // offset fields in the Local or Central directory
 61	            // record is too small to hold the required data,
 62	            // a Zip64 extended information record is created.
 63	            // The order of the fields in the zip64 extended
 64	            // information record is fixed, but the fields MUST
 65	            // only appear if the corresponding Local or Central
 66	            // directory record field is set to 0xFFFF or 0xFFFFFFFF.
 67	            // Original
 68	            // Size       8 bytes    Original uncompressed file size
 69	            // Compressed
 70	            // Size       8 bytes    Size of compressed data
 71	            // Relative Header
 72	            // Offset     8 bytes    Offset of local header record
 73	            // Disk Start
 74	            // Number     4 bytes    Number of the disk on which
 75	            // this file starts
 76	            if (size >= 8 && uncompressedSize == 0xFFFFFFFF) {
 77	              uncompressedSize = extraBytes.readUint64();
 78	              size -= 8;
 79	            }
 80	            if (size >= 8 && compressedSize == 0xFFFFFFFF) {
 81	              compressedSize = extraBytes.readUint64();
 82	              size -= 8;
 83	            }
